//! The interface string keys, generated by `build.rs` from `lang/en/*.strings`.

/// An ordinary interface string.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct Key(pub(crate) u16);

/// A string with plural forms, chosen by a count.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct PluralKey(pub(crate) u16);

impl Key {
    /// The key's name (`lng_*` or `qll_*`).
    pub fn name(self) -> &'static str {
        KEY_NAMES.get(usize::from(self.0)).copied().unwrap_or("")
    }
}

impl PluralKey {
    /// The key's name, without a form suffix.
    pub fn name(self) -> &'static str {
        KEY_NAMES.get(usize::from(self.0)).copied().unwrap_or("")
    }
}

/// A key's built-in English text.
#[derive(Debug, Clone, Copy)]
pub(crate) enum English {
    Text(&'static str),
    /// Indexed by [`super::parse::Form`]; `Other` is always present.
    Plural([Option<&'static str>; 6]),
}

/// The index of a key name (`lng_foo`, or `lng_foo#one` with its form
/// split off by the caller) in [`KEY_NAMES`].
pub(crate) fn index_of(name: &str) -> Option<usize> {
    KEY_NAMES.binary_search(&name).ok()
}

include!(concat!(env!("OUT_DIR"), "/lang_keys.rs"));
